        uint256 totalStaked_,
        uint256 weightedAverageTime_
    ) {
        UserInfo storage userInfo = users[user];
        totalStaked_ = userInfo.totalStaked;
        weightedAverageTime_ = this.calculateWeightedAverageHoldingPeriod(user);
    }

